//! Entries slice — Batch 57+ era (rules 354-373 of 373) — measured-GOAT +
//! paper distillations. Opened 2026-08-18 when `entries_gpu_06.rs` reached
//! the ~900-line threshold (Batches 43-56, rules 325-353). Category membership
//! lives ONLY in `KERNEL_CATEGORIES` (mod.rs) — never encode it here.

use crate::domains::kernel_opt::KernelRule;

/// Data table, not logic — grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<KernelRule> {
    vec![
        // ── smem-slot-role-reversal-needs-barrier ── distilled from the
        // measured-GOAT riir-ai Issue 715 fix (2026-08-17/18, commits
        // 9f9e68402 + 93d853582): the flash-attention online-softmax tile
        // loop shared an smem scratch across phases WITHOUT a barrier at
        // the two points where a slot's role reverses. Measured on the 27B
        // model, 256-token probe, same binary back-to-back: NONDETERMINISTIC
        // before (first divergent token index 71), BIT-IDENTICAL (3/3)
        // after. Five kernels shipped the races: 3 CubeCL
        // (qwen_attention_decode_f32, qwen_attention_decode_gated_f32,
        // qwen_attention_prefill_gated_f32) + 2 cudarc CUDA twins
        // (attention_decode_f32, attention_decode_f32_devpos) — the CubeCL
        // fix did NOT reach the cudarc arm (that arm dispatches hand-written
        // CUDA; grepping the CubeCL source proves nothing about which
        // kernels a given arm dispatches). Recurring class: Issue 612's
        // smem-corruption fix removed the destructive reduction but left
        // BOTH windows open.
        //
        // Distinct from smem-broadcast-scalar-then-parallel-scatter (E — the
        // broadcast pattern ASSUMES this discipline; this rule is the
        // required ordering when it is missing), from
        // smem-staging-gated-by-cross-thread-reuse (B35 — whether to stage
        // in smem at all; this is the barrier contract across a staged
        // buffer's lifetime), and from the barrier-elimination family
        // (warp-shuffle / plane-sized workgroups remove barriers by
        // construction — these two reversals can NEVER be removed while the
        // buffer is shared across phases).
        KernelRule {
            rule_id: "smem-slot-role-reversal-needs-barrier".to_string(),
            gpu_concept: "A shared-memory scratch whose slot ROLES reverse between phases needs a barrier at each reversal point. The two canonical windows in an online-softmax tile loop: (a) INTRA-ITERATION — every thread reads the reduction result smem[0], then a later phase has thread 0 OVERWRITE that same slot with its weight, with no barrier between: a slower warp reads a weight as the tile max, threads disagree on the softmax shift, and the tile's weights come out inconsistently scaled — length-independent, fires at any size; (b) LOOP BACK-EDGE — the last phase reads every smem[p] while the next iteration's first phase writes smem[tid] with no barrier between: a thread that finishes its read loop early clobbers a weight another thread has not consumed — reachable only when the loop trips more than once (n_tiles >= 2). Measured on the 27B model, 256-token probe, same binary back-to-back: NONDETERMINISTIC before (first divergent token index 71), BIT-IDENTICAL (3/3) after — a tolerance-only assert cannot see a race in the low mantissa bits. Both barriers must sit in BLOCK-UNIFORM control flow: the kernel's early returns (head_idx >= n_head, n_positions == 0) are uniform across the block, so no divergent-barrier deadlock is introduced. The fix must be audited against EVERY implementation twin of the same computation: the CubeCL fix did not reach the cudarc arm, because that arm dispatches hand-written CUDA — grepping one source tree proves nothing about which kernels a given arm dispatches. Recurring class: the prior fix for smem corruption in this loop (Issue 612) removed the destructive reduction but left both windows open. Distinct from smem-broadcast-scalar-then-parallel-scatter (the broadcast pattern that ASSUMES this discipline — this rule is the required ordering when it is missing), from smem-staging-gated-by-cross-thread-reuse (whether to stage in smem at all — this is the barrier contract across a staged buffer's lifetime), and from the barrier-elimination family (warp-shuffle reductions, plane-sized workgroups remove barriers by construction — this rule marks the two role reversals that can NEVER be removed while the buffer is shared across phases).".to_string(),
            ref_shape: "// naive: online-softmax tile loop sharing smem across phases with NO\n// barrier at the role reversals — race (a) intra-iteration, race (b) back-edge\nfn attention_decode_naive(scores: &[f32], smem: &mut [f32], tid: usize,\n                          n_tiles: usize, cube_size: usize) -> f32 {\n    let mut running_max = f32::NEG_INFINITY;\n    let mut running_sum = 0.0f32;\n    for tile in 0..n_tiles {\n        // Phase 1: each thread writes its local score (PRODUCER)\n        let base = tile * cube_size + tid;\n        smem[tid] = if base < scores.len() { scores[base] } else { f32::NEG_INFINITY };\n        barrier();\n        // Phase 2: max-reduction tree — smem[0] becomes the tile max\n        let mut stride = cube_size / 2;\n        while stride > 0 {\n            if tid < stride && smem[tid + stride] > smem[tid] {\n                smem[tid] = smem[tid + stride];\n            }\n            barrier();\n            stride /= 2;\n        }\n        // RACE (a): every thread reads smem[0] as tile_max; Phase 3 below\n        // has thread 0 overwrite that SAME slot with its weight — no\n        // barrier between: a slow warp reads a weight as the max, threads\n        // disagree on the softmax shift, weights scale inconsistently.\n        // Length-independent: fires at any n_positions.\n        let tile_max = smem[0];\n        let my_score = smem[tid];\n        if tid == 0 {\n            smem[0] = (my_score - tile_max).exp(); // thread 0 overwrites\n        }\n        let new_max = if tile_max > running_max { tile_max } else { running_max };\n        running_sum *= (new_max - running_max).exp();\n        running_sum += (my_score - new_max).exp();\n        running_max = new_max;\n        // Phase 4: every thread reads every smem[p] (the weights)\n        let mut acc = 0.0f32;\n        for p in 0..cube_size {\n            acc += smem[p];\n        }\n        running_sum += acc;\n        // RACE (b): loop back-edge — the next tile's Phase 1 writes smem[tid]\n        // with NO barrier: a thread that finishes its read loop early\n        // clobbers a weight another thread has not yet consumed.\n        // Reachable only when n_tiles >= 2 (n_positions > cube_size).\n    }\n    1.0 / running_sum // nondeterministic run-to-run: races flip low mantissa bits\n}\nfn barrier() {}".to_string(),
            opt_pattern: "// optimized: a barrier at EACH role reversal — (a) between the smem[0]\n// read and the thread-0 overwrite, (b) on the loop back-edge; both sit\n// in block-uniform control flow (the early returns are uniform)\nfn attention_decode_fixed(scores: &[f32], smem: &mut [f32], tid: usize,\n                          n_tiles: usize, cube_size: usize) -> f32 {\n    let mut running_max = f32::NEG_INFINITY;\n    let mut running_sum = 0.0f32;\n    for tile in 0..n_tiles {\n        smem[tid] = scores[tile * cube_size + tid]; // Phase 1 (producer)\n        barrier();\n        let mut stride = cube_size / 2;             // Phase 2 (reduce)\n        while stride > 0 {\n            if tid < stride && smem[tid + stride] > smem[tid] {\n                smem[tid] = smem[tid + stride];\n            }\n            barrier();\n            stride /= 2;\n        }\n        let tile_max = smem[0]; // every thread reads the result (consumer)\n        barrier(); // REVERSAL (a): smem[0] flips result -> thread-0 weight\n        let my_score = smem[tid];\n        if tid == 0 {\n            smem[0] = (my_score - tile_max).exp(); // safe: all lanes read it\n        }\n        let new_max = if tile_max > running_max { tile_max } else { running_max };\n        running_sum *= (new_max - running_max).exp();\n        running_sum += (my_score - new_max).exp();\n        running_max = new_max;\n        let mut acc = 0.0f32;                       // Phase 4 (consumer)\n        for p in 0..cube_size {\n            acc += smem[p];\n        }\n        running_sum += acc;\n        barrier(); // REVERSAL (b): back-edge — next Phase 1 writes smem[tid]\n    }\n    1.0 / running_sum // bit-identical run-to-run (measured 3/3 on the 27B)\n}\nfn barrier() {}".to_string(),
        },
        // ── tile-loop-back-edge-needs-multi-tile-bitexact-gate ── distilled
        // from the measured-GOAT riir-ai Issue 715 regression gate
        // (2026-08-17, commit 9f9e68402): every prior decode test used
        // n_positions <= 200 — strictly inside ONE 256-wide tile — so the
        // tile-loop body ran once and its back-edge was NEVER taken: race
        // (b) (and any back-edge carry) was untestable by construction. The
        // new gate pins n_positions=300 (n_tiles=2) and asserts, over 64
        // repeats, BOTH correctness vs the CPU reference AND bit-exact
        // reproducibility — validated in BOTH directions: fails on run 0
        // with max_diff=0.0586 when the barriers are removed, passes with
        // them. Second in-tree instance: riir-ai Issue 710 H10 — the q8kv
        // multi-tile path (cross-tile rescale + tail-tile guard) had ZERO
        // coverage at n_positions > 256 until a 2-tile fixture was written.
        //
        // Distinct from size-gate-covers-every-cost-factor (B46 — a dispatch
        // cost gate's INPUT completeness; this is a test fixture's COVERAGE
        // completeness), from verify-once-at-trust-boundary (B32b — WHERE
        // verification happens; this is what the verification must be shaped
        // like to see loop-boundary defects), and from the benign-case-only
        // probe corollary in buffer-length-derived-from-allocation-not-binding
        // (B55 — a probe measuring only the benign case answers wrongly;
        // here the fixture population never enters the defective region).
        KernelRule {
            rule_id: "tile-loop-back-edge-needs-multi-tile-bitexact-gate".to_string(),
            gpu_concept: "A loop whose trip count crosses an iteration boundary only past a size threshold — a tile loop trips twice only when n > tile size, a chunked recurrence carries only on partial chunks — hides every back-edge defect from any fixture population whose inputs all sit inside ONE iteration: the loop body runs once, the back-edge is never taken, and back-edge bugs (carry/rescale races, cross-tile state, tail-tile guards) are untestable BY CONSTRUCTION. The gate needs BOTH halves: (1) at least one fixture with n strictly greater than the boundary (n_positions=300 > cube_size=256 → n_tiles=2) so the back-edge actually executes; and (2) a bit-exact REPRODUCIBILITY assert over repeats of the SAME binary — a tolerance-only assert cannot see a race in the low mantissa bits, because two runs of identical code agreeing to 1e-5 still differ bitwise under a race. Validate the gate in BOTH directions: it must fail with the defect present (the 715 gate fails on run 0 with max_diff=0.0586 when the barriers are removed) and pass with the fix — a gate that cannot fail proves nothing. The fixture-population bias is silent: every prior decode test used n_positions <= 200 and passed, not because the kernel was correct but because the code under test never ran. Second in-tree instance of the class: the q8kv multi-tile path (cross-tile rescale + tail-tile guard) had zero coverage at n_positions > 256 until a 2-tile fixture was written (Issue 710 H10). Distinct from size-gate-covers-every-cost-factor (a dispatch cost gate's input completeness — this is a test fixture's coverage completeness), from verify-once-at-trust-boundary (where verification happens — this is what the verification must be shaped like to see loop-boundary defects), and from the benign-case-only probe corollary in buffer-length-derived-from-allocation-not-binding (a probe measuring only the benign case answers wrongly — here the fixture population never enters the defective region at all).".to_string(),
            ref_shape: "// naive gate: every fixture fits inside ONE tile — the loop back-edge\n// never executes, so a back-edge race passes the whole suite\nfn decode_test_single_tile_only() {\n    // n_positions=200 < cube_size=256 -> n_tiles=1: the tile-loop body\n    // runs ONCE; its back-edge (and any cross-tile carry) is never taken\n    for n_positions in [1usize, 64, 128, 200] {\n        let out = decode(n_positions);\n        // tolerance-only assert: a race in the low mantissa bits lands\n        // within 1e-5 — two bitwise-different runs both \"pass\"\n        assert!((out - cpu_reference(n_positions)).abs() < 1e-5);\n    }\n}\nfn decode(_n: usize) -> f32 { 0.0 }\nfn cpu_reference(_n: usize) -> f32 { 0.0 }".to_string(),
            opt_pattern: "// optimized gate: cross the tile boundary + assert bit-exact reproducibility\nfn decode_multi_tile_deterministic() {\n    let n_positions = 300; // > cube_size=256 -> n_tiles=2: the back-edge RUNS\n    let expected = cpu_reference(n_positions);\n    let mut first: Option<Vec<f32>> = None;\n    for _ in 0..64 {\n        // repeats of the SAME binary: a race flips low bits run-to-run\n        let out = decode(n_positions);\n        assert!((out - expected).abs() < 1e-5); // correctness vs reference\n        if let Some(prev) = &first {\n            // BIT-exact reproducibility: a tolerance assert cannot see a\n            // race in the low mantissa bits — bitwise equality is the only\n            // race-proof assert\n            assert_eq!(out, *prev, \"run-to-run divergence = a race, not noise\");\n        } else {\n            first = Some(out);\n        }\n    }\n}\n// validated in BOTH directions: fails on run 0 (max_diff=0.0586) with the\n// barriers removed, passes with them — a gate that cannot fail proves nothing\nfn decode(_n: usize) -> Vec<f32> { vec![0.0; 4] }\nfn cpu_reference(_n: usize) -> Vec<f32> { vec![0.0; 4] }".to_string(),
        },
        // ── async-htod-host-source-outlives-copy ── distilled from the
        // cudarc decode-forward graph path (Issue 618/696-era staging fields,
        // ternary_deltanet_gpu_forward_cudarc.rs lines 261-268 + 1408-1434):
        // the per-call pos/token scalars ride PERSISTENT host fields into
        // the async memcpy — a stack local would dangle before the GPU
        // reads it, silently feeding garbage positions to the decode loop.
        //
        // The host-side lifetime complement of the readback-timing family
        // (B26/B27 pin device transients for deferred DtoH; this pins HOST
        // memory for deferred HtoD).
        KernelRule {
            rule_id: "async-htod-host-source-outlives-copy".to_string(),
            gpu_concept: "An async host-to-device memcpy reads the host pointer at GPU-completion time, not at call time — a stack local passed as the copy source dangles when its frame drops before the copy executes, and the GPU silently reads whatever now occupies the dead stack slot (wrong token/position, no error, decode continues on garbage). Route every per-call host scalar/vector through persistent host staging fields (struct fields whose lifetime equals the pipeline's), write the field, then hand slice::from_ref(&field) to the async copy. This is the host-side complement of the readback-timing family — defer-readback-until-after-submit pins device transients for deferred DtoH and snapshot-transient-grad-for-deferred-download pins device values via encoder copies; this rule pins HOST memory for deferred HtoD. Distinct from cuda-graph-scalar-via-device-pointer (what the captured graph bakes — this covers where the pre-launch upload's source must live) and from staging-packed-uniforms-encoder-ordered-copies (device-side uniform staging — this is the host source lifetime).".to_string(),
            ref_shape: "// naive: stack local as the async-copy source — the frame drops before the\n// GPU reads the pointer, so the device token/pos become silent garbage\nstruct Stream;\nstruct DevBuf(i32);\nstruct Graph;\nimpl Stream {\n    fn memcpy_htod(&self, src: &[i32], dst: &mut DevBuf) {}\n}\nfn launch_graph(_g: &Graph) {}\nfn forward_graph_naive(stream: &Stream, token_id: usize, pos: usize) {\n    let tok: i32 = token_id as i32; // stack local — dropped at fn return\n    let p: i32 = pos as i32;\n    // cuMemcpyHtoDAsync_v2 reads &tok at GPU-completion time — LATER\n    stream.memcpy_htod(std::slice::from_ref(&tok), &mut DevBuf(0));\n    stream.memcpy_htod(std::slice::from_ref(&p), &mut DevBuf(0));\n    launch_graph(&Graph); // no error: the GPU reads whatever now occupies\n} // the dead stack slot — wrong token/pos".to_string(),
            opt_pattern: "// optimized: persistent host staging fields — lifetime = the pipeline's\nstruct Stream;\nstruct DevBuf(i32);\nstruct HostStaging {\n    token_host: i32,\n    pos_host: i32,\n}\nstruct Fwd {\n    acts: HostStaging,\n    stream: Stream,\n    pos: usize,\n}\nimpl Stream {\n    fn memcpy_htod(&self, src: &[i32], dst: &mut DevBuf) {}\n}\nimpl Fwd {\n    fn forward_graph(&mut self, token_id: usize) {\n        self.acts.token_host = token_id as i32; // write the FIELD, not a local\n        self.acts.pos_host = self.pos as i32;\n        let s = &self.stream;\n        let a = &mut self.acts;\n        // borrows the persistent field: valid as long as self lives — the\n        // async copy can never race a dead stack frame\n        s.memcpy_htod(std::slice::from_ref(&a.token_host), &mut DevBuf(0));\n        s.memcpy_htod(std::slice::from_ref(&a.pos_host), &mut DevBuf(0));\n    }\n}".to_string(),
        },

        // ── captured-graph-bakes-buffer-addresses ── distilled from the
        // Issue 696 graph lifecycle (ternary_deltanet_gpu_forward_cudarc.rs
        // lines 815-838 set_lora/clear_lora invalidate; 1513-1517 the
        // defensive-invalidate note; 3288-3299 reset_state zeroes IN PLACE
        // so addresses stay stable — "previously the replaced buffers left
        // the graph replaying against freed memory").
        KernelRule {
            rule_id: "captured-graph-bakes-buffer-addresses".to_string(),
            gpu_concept: "A captured CUDA graph bakes in every buffer address it referenced, not just kernel-presence decisions — after capture, state mutators split into two classes. Address-stable mutators (in-place memset_zeros: content mutation, identity preserved) let the graph stay valid and replay against the same, now-zeroed, buffers. Identity-changing mutators (any allocation/free of buffers the graph touches — attaching an adapter allocates adapter+scratch, detaching frees them, a reset that REPLACES buffers) MUST drop the graph so the next call lazily re-captures, else replay runs against freed pointers: silent garbage or ILLEGAL_ADDRESS. Both halves are decisions: invalidate on identity change AND prefer in-place content mutation precisely so an expensive capture survives. Distinct from hot-swap-weights-preserve-autotune-caches (keep runtime caches ALIVE across weight swaps — here the graph must DIE on identity change) and from cuda-graph-scalar-via-device-pointer (baked scalar VALUES via device buffers — this is baked buffer IDENTITY under mutation).".to_string(),
            ref_shape: "// naive: mutators change buffer identity, the captured graph keeps stale addresses\nstruct Stream;\nstruct Graph;\nstruct Lora;\nstruct Buf;\nstruct Fwd {\n    lora: Option<Buf>,\n    lora_ax: Option<Buf>,\n    states: Vec<Buf>,\n    graph: Option<Graph>,\n}\nfn upload_adapter(_s: &Stream, _l: &Lora) -> Buf {\n    Buf\n}\nfn alloc_zeros(_s: &Stream) -> Buf {\n    Buf\n}\nfn alloc_states(_s: &Stream) -> Vec<Buf> {\n    vec![Buf]\n}\nfn set_lora_naive(fwd: &mut Fwd, lora: &Lora, stream: &Stream) {\n    fwd.lora = Some(upload_adapter(stream, lora)); // allocates NEW device buffers\n    fwd.lora_ax = Some(alloc_zeros(stream)); // rank scratch — NEW allocation\n    // fwd.graph still holds the OLD address set: nothing invalidates it\n}\nfn reset_state_naive(fwd: &mut Fwd, stream: &Stream) {\n    fwd.states = alloc_states(stream); // a reset that REPLACES buffers kills\n} // the graph — replay writes FREED memory".to_string(),
            opt_pattern: "// optimized: classify mutators — identity change invalidates, content change stays\nstruct Stream;\nstruct Graph;\nstruct Lora;\nstruct Buf;\nstruct Fwd {\n    lora: Option<Buf>,\n    states: Vec<Buf>,\n    graph: Option<Graph>,\n    pos: usize,\n}\nfn upload_adapter(_s: &Stream, _l: &Lora) -> Buf {\n    Buf\n}\nfn set_lora(fwd: &mut Fwd, lora: &Lora, stream: &Stream) {\n    fwd.lora = Some(upload_adapter(stream, lora));\n    fwd.graph = None; // identity changed: drop so the next call re-captures\n}\nfn clear_lora(fwd: &mut Fwd) {\n    fwd.lora = None; // frees adapter buffers the graph references\n    fwd.graph = None; // a captured graph would replay against freed pointers\n}\nimpl Stream {\n    fn memset_zeros(&self, _b: &mut Buf) {}\n}\nfn reset_state(fwd: &mut Fwd, stream: &Stream) {\n    for state in &mut fwd.states {\n        stream.memset_zeros(state); // zero IN PLACE: addresses stable ->\n    } // the captured graph SURVIVES the reset\n    fwd.pos = 0;\n}".to_string(),
        },

        // ── output-buffer-rotation-pool-multi-forward ── distilled from the
        // Issue 717 G3b speculative verify seam (ternary_deltanet_gpu_forward_
        // cudarc.rs lines 283-290 pool sizing, 661-675 construction, 1767-1813
        // the rotation trace + the field-keeps-last contract, 1831-1838 the
        // ONE-sync read).
        KernelRule {
            rule_id: "output-buffer-rotation-pool-multi-forward".to_string(),
            gpu_concept: "K sequentially-dependent forwards that all write the SAME output field need per-forward result retention without per-forward syncs — swap the field's buffer handle with pool[i] before each dispatch (mem::swap is an O(1) ownership exchange, zero bytes move across the bus); each forward then writes a different allocation; ONE sync at the end; K+1 position-aligned reads ([pre-spec, fwd0..fwd(K-1)]). The field deliberately KEEPS the last forward's buffer between cycles (never un-rotated mid-run) — that is what makes the next cycle's out[0] the live pre-speculation prediction. At run end, graph-consuming callers must restore or invalidate (captured graphs bake buffer addresses — composes with captured-graph-bakes-buffer-addresses). Distinct from activation-checkpoint-as-handle-clone-deferred-batch-readback (save-medium for backward replay — this is output staging across pipelined forwards), batched-downloads-single-sync-cycle (read mechanics — this is the buffer-identity rotation that makes the no-sync sequence possible), and make-unmake-over-clone-per-candidate (host-state rollback — this is device output staging).".to_string(),
            ref_shape: "// naive: sync + download after EVERY forward — the pipeline drains K times\nstruct Stream;\nstruct Fwd;\nimpl Stream {\n    fn synchronize(&self) {}\n}\nfn set_input(_f: &mut Fwd, _t: usize) {}\nfn dispatch(_f: &mut Fwd) {}\nfn read_logits(_f: &Fwd) -> Vec<f32> {\n    vec![0.0]\n}\nfn verify_naive(fwd: &mut Fwd, drafts: &[usize], stream: &Stream) -> Vec<Vec<f32>> {\n    let mut out = vec![read_logits(fwd)]; // sync #0 (pre-spec result)\n    for &tok in drafts {\n        set_input(fwd, tok);\n        dispatch(fwd);\n        stream.synchronize(); // per-forward sync drains everything queued\n        out.push(read_logits(fwd)); // + K x vocab x 4 bytes downloaded\n    }\n    out\n}".to_string(),
            opt_pattern: "// optimized: rotate the output field through a pre-allocated pool — zero\n// copies, zero mid-cycle syncs, K+1 position-aligned results\nstruct Buf;\nstruct Fwd {\n    logits: Buf,\n    argmax: Buf,\n}\nstruct SpecPools {\n    logits_pool: Vec<Buf>,\n    argmax_pool: Vec<Buf>,\n}\nfn set_input(_f: &mut Fwd, _t: usize) {}\nfn dispatch(_f: &mut Fwd) {}\nfn spec_verify_dispatch(fwd: &mut Fwd, pools: &mut SpecPools, drafts: &[usize]) {\n    for (i, &tok) in drafts.iter().enumerate() {\n        // O(1) ownership exchange — zero bytes move across the bus\n        std::mem::swap(&mut fwd.logits, &mut pools.logits_pool[i]);\n        std::mem::swap(&mut fwd.argmax, &mut pools.argmax_pool[i]);\n        set_input(fwd, tok);\n        dispatch(fwd); // writes pool[i]'s allocation — queued, not synced\n    }\n}\n// then ONE sync, and read [pool[0..k], fwd.logits] = [pre-spec, fwd0..fwd(k-1)]\n// — K+1 results. The field KEEPS the last buffer between cycles (never\n// un-rotated mid-run): that makes the NEXT cycle's out[0] the live\n// pre-speculation prediction. At run end, graph-consuming callers must\n// restore/invalidate — captured graphs bake buffer addresses.".to_string(),
        },

        // ── mid-pipeline-device-alloc-is-implicit-sync ── distilled from the
        // SPEC_MAX_K pool rationale (ternary_deltanet_gpu_forward_cudarc.rs
        // lines 283-290 + 632-635: "so the verify path never calls
        // alloc_zeros mid-cycle: cuMemAlloc can implicitly synchronize the
        // device, which would drain the pipeline between the K verify
        // forwards and break the no-intermediate-sync contract").
        KernelRule {
            rule_id: "mid-pipeline-device-alloc-is-implicit-sync".to_string(),
            gpu_concept: "cuMemAlloc can implicitly synchronize the device — any allocation inside a deliberately no-intermediate-sync dispatch sequence (K pipelined forwards between two syncs) is a HIDDEN BARRIER that drains the pipeline and voids the no-sync contract that is the entire point of the sequence. Pre-allocate the cycle's whole working set (result pools, checkpoint backups, scratch) at construction, sized to the statically known maximum (SPEC_MAX_K): allocation-free-by-construction, and what looked like a nice-to-have pre-allocation is actually a correctness precondition for pipelining. Distinct from the explicit-sync family (no-blocking-sync-in-async-pipeline, batched-downloads-single-sync-cycle — visible sync CALLS; this is a hidden sync hiding inside an allocation call), from superset-sized-scratch-across-variants (sizing discipline to avoid churn — here the failure is a silent pipeline drain, not churn cost), and from transient-spike-pins-persistent-scratch (when NOT to size for max transiently — this pool is recurring by design, bounded by the max K constant).".to_string(),
            ref_shape: "// naive: allocate result storage inside the pipelined sequence — each\n// cuMemAlloc is a potential device-wide sync\nstruct Stream;\nstruct Buf;\nimpl Stream {\n    fn alloc_zeros(&self, _n: usize) -> Buf {\n        Buf\n    }\n    fn synchronize(&self) {}\n}\nfn vocab() -> usize {\n    248_320\n}\nfn forward_into(_b: &Buf) {}\nfn verify_naive(stream: &Stream, k: usize) {\n    for _i in 0..k {\n        let out = stream.alloc_zeros(vocab()); // cuMemAlloc may implicitly\n        forward_into(&out); // synchronize the DEVICE — the pipeline drains\n    } // mid-sequence, voiding the no-intermediate-sync contract\n    stream.synchronize();\n}".to_string(),
            opt_pattern: "// optimized: the cycle's whole buffer set exists before the first dispatch\nstruct Stream;\nstruct Buf;\nimpl Stream {\n    fn alloc_zeros(&self, _n: usize) -> Buf {\n        Buf\n    }\n}\nfn vocab() -> usize {\n    248_320\n}\nfn sync() {}\nfn forward_into(_b: &Buf) {}\nconst SPEC_MAX_K: usize = 8; // statically known maximum drafts per cycle\nstruct SpecPools {\n    logits_pool: Vec<Buf>,\n    argmax_pool: Vec<Buf>,\n}\nfn build_pools(stream: &Stream) -> SpecPools {\n    // paid ONCE at construction, sized to the WORST cycle — the verify path\n    // then never calls alloc_zeros mid-cycle\n    SpecPools {\n        logits_pool: (0..SPEC_MAX_K).map(|_| stream.alloc_zeros(vocab())).collect(),\n        argmax_pool: (0..SPEC_MAX_K).map(|_| stream.alloc_zeros(1)).collect(),\n    }\n}\nfn verify(pools: &SpecPools, k: usize) {\n    assert!((1..=SPEC_MAX_K).contains(&k));\n    for i in 0..k {\n        forward_into(&pools.logits_pool[i]); // zero allocs inside the loop\n    }\n    sync(); // the one legitimate sync, at the sequence boundary\n}".to_string(),
        },

        // ── capture-region-dispatch-only ── distilled from the CUDA-graph
        // capture contract (ternary_deltanet_gpu_forward_cudarc.rs lines
        // 1359-1365 dispatch-only split, 1392-1398 preconditions, 1480-1487
        // pre-upload, 1497-1509 sync/dtoh + pos increment OUTSIDE the
        // graph: "the graph itself doesn't run host-side code").
        KernelRule {
            rule_id: "capture-region-dispatch-only".to_string(),
            gpu_concept: "The captured region records GPU work ONLY — host-side effects inside it (counter increments, state mutation) execute ONCE at capture time and NEVER on replay: a pos += 1 baked at capture freezes the position for every subsequent replay, silent wrongness with no error. Syncs and downloads are not capturable at all (capture fails or records a malformed graph). Structure the hot path as a dispatch-only function (all launches, no sync/dtoh/host bookkeeping); move sync + download + host-side position advancement AFTER graph.launch(); and satisfy the wrapper-runtime preconditions: disable per-buffer event/sync tracking BEFORE any allocation, capture on a non-default stream (the null stream is not capturable), and pre-upload the instantiated graph once to absorb first-launch setup overhead. Distinct from cuda-graph-scalar-via-device-pointer (HOW per-launch inputs reach the graph via device buffers — this is WHAT must stay out of the region plus the preconditions for capture to succeed at all).".to_string(),
            ref_shape: "// naive: the forward mixes dispatches with host effects + sync — capture\n// bakes/aborts: pos freezes at capture time, every replay reuses it\nstruct Fwd {\n    pos: usize,\n}\nstruct Stream;\nimpl Stream {\n    fn synchronize(&self) {}\n}\nfn run_layers(_f: &mut Fwd) {}\nfn download_logits(_f: &Fwd) -> Vec<f32> {\n    vec![0.0]\n}\nfn forward_token_naive(fwd: &mut Fwd, stream: &Stream) -> Vec<f32> {\n    run_layers(fwd); // contains fwd.pos += 1 — a HOST effect: executes ONCE\n    // at capture, NEVER on replay — position frozen for every launch\n    stream.synchronize(); // NOT capturable — capture fails / malformed graph\n    download_logits(fwd) // silent wrongness: no error, stale position\n}".to_string(),
            opt_pattern: "// optimized: split dispatch from sync/readback; host bookkeeping after launch\nstruct Fwd {\n    pos: usize,\n    graph: Option<Graph>,\n}\nstruct Stream;\nstruct Graph;\nimpl Stream {\n    fn synchronize(&self) {}\n    fn begin_capture(&self) {}\n    fn end_capture(&self) -> Graph {\n        Graph\n    }\n}\nimpl Graph {\n    fn upload(&self) {}\n    fn launch(&self) {}\n}\nfn disable_event_tracking() {}\nfn run_layers_devpos(_f: &mut Fwd) {}\nfn upload_scalars_devpos(_f: &Fwd, _s: &Stream) {}\nfn download_logits(_f: &Fwd) -> Vec<f32> {\n    vec![0.0]\n}\nfn forward_dispatch_only(fwd: &mut Fwd) {\n    run_layers_devpos(fwd); // launches ONLY — no host effects inside\n}\nfn capture(fwd: &mut Fwd, stream: &Stream) {\n    disable_event_tracking(); // REQUIRED before any allocation, else errors\n    stream.begin_capture(); // on a NON-DEFAULT stream (null not capturable)\n    forward_dispatch_only(fwd);\n    let graph = stream.end_capture();\n    graph.upload(); // pre-upload absorbs first-launch setup overhead\n    stream.synchronize();\n    fwd.graph = Some(graph);\n}\nfn forward_token_graph(fwd: &mut Fwd, stream: &Stream) -> Vec<f32> {\n    upload_scalars_devpos(fwd, stream); // pos/token via device buffers\n    fwd.graph.as_ref().unwrap().launch(); // replays GPU work only\n    stream.synchronize(); // OUTSIDE the captured region\n    let logits = download_logits(fwd);\n    fwd.pos += 1; // host effect AFTER launch — runs every call, not once\n    logits\n}".to_string(),
        },

        // ── occupancy-grid-cap-refuted-uncapped-default ── distilled from
        // the Issue 705 / Bench 684 measured negative (the measured-verdict
        // doc at ternary_deltanet_gpu_forward_cudarc.rs lines 145-158 + the
        // construction-time occupancy query + env override at 449-486). The
        // negative result was never distilled at resolution time — captured
        // here by the Batch 58 file-mining pass.
        KernelRule {
            rule_id: "occupancy-grid-cap-refuted-uncapped-default".to_string(),
            gpu_concept: "Capping a launch grid at the occupancy-derived residency limit (SMs x blocks/SM = 768 on the 4090) to eliminate the wave-quantization tail is REFUTED by measurement — the hardware block scheduler's wavefront locality given to the naive oversized grid outweighs the partial tail wave it pays: the Bench 684 sweep measured uncapped 87.1 vs 768-cap 84.9-86.2 vs 1024-cap 82.1 vs 512-cap 75.6 graph tok/s (a 1-2% LOSS at every tested size), and the wave-tail theory is independently refuted by the exact-1-wave counter-example (a 768-block launch measured 706 GB/s vs lm_head's 854 — tails were never the differentiator). Ship the uncapped one-warp-per-row grid as the default; retain the cap behind an env override resolved ONCE at construction purely as the measurement/tuning apparatus. Distinct from grid-stride-loop (the iteration-coverage pattern — this is the launch-geometry DECISION of whether to cap it) and from fold-query-tokens-for-occupancy (filling idle SMs with more work vs refusing to shrink the grid).".to_string(),
            ref_shape: "// ref (the plausible-but-losing \"optimization\"): full-residency capped grid\nstruct Kernels {\n    sm_count: usize,\n    max_blocks_per_sm: usize,\n}\nimpl Kernels {\n    fn launch_persistent(&self, _grid: usize) {}\n}\nfn launch_capped(fns: &Kernels, rows: usize) {\n    let residency = fns.sm_count * fns.max_blocks_per_sm; // 128 * 6 = 768 on 4090\n    let grid = ((rows + 7) / 8).min(residency); // cap \"eliminates\" the tail wave\n    fns.launch_persistent(grid); // MEASURED 1-2% LOSS at every size (Bench 684:\n} // uncapped 87.1 vs 768-cap 84.9-86.2 vs 1024-cap 82.1 vs 512-cap 75.6 tok/s)".to_string(),
            opt_pattern: "// opt: uncapped default + the cap as opt-in measurement apparatus\nstruct Kernels;\nimpl Kernels {\n    fn launch_persistent(&self, _grid: usize) {}\n}\nfn resolve_grid_cap() -> u32 {\n    // resolved ONCE at construction, never on the launch path\n    match std::env::var(\"RIIR_GEMV_PERSISTENT_GRID\") {\n        Ok(v) => v.parse().unwrap_or(u32::MAX),\n        Err(_) => u32::MAX, // UNcapped — the measured-best default\n    }\n}\nfn launch(fns: &Kernels, rows: usize, cap: u32) {\n    let grid = ((rows + 7) / 8).min(cap as usize); // cap = u32::MAX in prod\n    fns.launch_persistent(grid); // the override exists to RE-BENCH the refuted\n} // wave-tail theory, not to ship it — the hardware block scheduler's\n// wavefront locality beats the partial tail wave it pays".to_string(),
        },

        // ── write-before-read-state-skips-checkpoint ── distilled from the
        // Issue 717 G3b GPU-side speculative checkpoint (ternary_deltanet_
        // gpu_forward_cudarc.rs lines 1899-1928: async dtod of the
        // read-modify set only; "the attention KV cache needs no backup:
        // decode at position p reads [0..=p] and the append for p
        // overwrites the stale speculative entry before the decode kernel
        // runs").
        KernelRule {
            rule_id: "write-before-read-state-skips-checkpoint".to_string(),
            gpu_concept: "A speculative-execution checkpoint only needs to back up state whose mutation is READ-MODIFY at the replay position (recurrent/conv state: every step reads then updates in place); state that is WRITE-BEFORE-READ (an append-only position-indexed cache: decode at position p reads [0..=p], and re-execution's append for p overwrites the stale speculative entry before any read) is repaired by re-execution itself — backing it up copies the largest per-layer state for nothing. The backup is async device-to-device copies into pre-allocated twins with ZERO CPU-GPU sync (stream FIFO order guarantees completion before the next forward reads state); host-side bookkeeping (the position counter) is snapshotted separately by the caller so the checkpoint stays sync-free. Distinct from append-cache-rewind-overwrite-in-place (rewind MECHANICS for the cache itself — this decides the checkpoint SET need not include the cache), from make-unmake-over-clone-per-candidate (host game-state rollback), and from activation-checkpoint-as-handle-clone-deferred-batch-readback (checkpoint medium for backward training — this is speculative-execution rollback).".to_string(),
            ref_shape: "// naive: back up EVERYTHING before speculating — including the append-only cache\nstruct Stream;\nstruct Buf;\nstruct Layer {\n    deltanet_state: Buf,\n    conv_state: Buf,\n    kv_cache: Buf,\n}\nstruct Fwd {\n    pos: usize,\n    saved_pos: usize,\n    layers: Vec<Layer>,\n}\nfn backup(_s: &Stream, _b: &Buf) {}\nfn checkpoint_naive(fwd: &mut Fwd, stream: &Stream) {\n    for layer in &fwd.layers {\n        backup(stream, &layer.deltanet_state); // read-modify: NEEDED\n        backup(stream, &layer.conv_state); // read-modify: NEEDED\n        backup(stream, &layer.kv_cache); // [block_size x kvd] per layer — WASTED:\n    } // rollback + re-execution overwrites position p's entry before any read\n    fwd.saved_pos = fwd.pos; // mixing host bookkeeping into the checkpoint\n} // couples the API and invites a hidden sync".to_string(),
            opt_pattern: "// optimized: dtod-copy ONLY the read-modify set; KV skipped by read/write order\nstruct Stream;\nstruct Buf;\nstruct St {\n    deltanet_state: Option<Buf>,\n    conv_state: Option<Buf>,\n}\nstruct Fwd {\n    states: Vec<St>,\n    backups: Vec<St>,\n}\nimpl Stream {\n    fn memcpy_dtod(&self, _src: &Buf, _dst: &mut Buf) {}\n}\nfn checkpoint_speculative_gpu(fwd: &mut Fwd, stream: &Stream) {\n    for (st, bk) in fwd.states.iter().zip(fwd.backups.iter_mut()) {\n        if let (Some(src), Some(dst)) = (&st.deltanet_state, &mut bk.deltanet_state) {\n            stream.memcpy_dtod(src, dst); // async — stream FIFO order\n        } // guarantees completion before the next verify forward: ZERO sync\n        if let (Some(src), Some(dst)) = (&st.conv_state, &mut bk.conv_state) {\n            stream.memcpy_dtod(src, dst);\n        }\n    }\n    // attention KV cache: NO backup — decode at pos p reads [0..=p] and the\n    // append for p overwrites the stale speculative entry first\n    // (write-before-read: re-execution itself repairs the cache)\n}\n// caller snapshots pos separately: let p = fwd.position(); ... rollback(p)".to_string(),
        },

        // ── same-input-gemv-segments-single-launch ── distilled from the
        // Issue 697 multi-GEMV launcher (ternary_deltanet_gpu_forward_
        // cudarc.rs lines 3435-3483: the nsys 497-launches/token
        // attribution, the <=4 segment contract, and the m=0 pad —
        // "zero-length segments match no rows, so their pointers are
        // never dereferenced — reuse segment 0's pointers").
        KernelRule {
            rule_id: "same-input-gemv-segments-single-launch".to_string(),
            gpu_concept: "When several small GEMV projections consume the SAME quantized input vector (qkv+z+a+b; gate+up; q+k+v), one launch per projection pins every launch to the kernel-latency floor — nsys attribution measured 497 GEMV launches/token with the m=48 projections at the ~5.6 microsecond latency floor (540 microseconds/token for 6.6 MB of weights). Group same-input GEMVs into ONE multi-segment launch (a segment = weights+output+m descriptor, at most 4 per launch) so tiny rows ride along at ~zero marginal cost; pad unused segment slots by reusing segment 0's pointers (m=0 matches no rows — never dereferenced); caller invariant: every segment shares the same input dim n. The generic middle option between fan-out-shared-input-single-sync (shared upload, N separate launches) and the bespoke fused pair (fuse-gate-up-gemv-activation — one fixed pair WITH activation; this batches arbitrary same-input segments with NO bespoke kernel). Honest caveat in-source: the grid cap that rides along is refuted (occupancy-grid-cap-refuted-uncapped-default) — the batching is the win, not the cap.".to_string(),
            ref_shape: "// naive: one launch per projection — each pays launch latency + a wave tail\nstruct Kernels;\nstruct Buf;\nstruct Weights {\n    m: usize,\n}\nimpl Kernels {\n    fn launch_gemv(&self, _w: &Weights, _x: &Buf, _o: &mut Buf) {}\n}\nfn quantize_into(_k: &Kernels, _x: &mut Buf) {}\nfn project_naive(fns: &Kernels, x_quant: &mut Buf, outs: &mut [Buf]) {\n    quantize_into(fns, x_quant); // once (good)\n    fns.launch_gemv(&Weights { m: 3072 }, x_quant, &mut outs[0]); // ~5.6 us\n    fns.launch_gemv(&Weights { m: 48 }, x_quant, &mut outs[1]); // floor\n    fns.launch_gemv(&Weights { m: 48 }, x_quant, &mut outs[2]); // floor\n    fns.launch_gemv(&Weights { m: 48 }, x_quant, &mut outs[3]); // floor: launch\n} // overhead dominates tiny projections (497 launches/token measured)".to_string(),
            opt_pattern: "// optimized: ONE multi-segment launch per same-input group; pad to 4 slots\nstruct Kernels;\nstruct Buf;\n#[derive(Clone)]\nstruct Segment {\n    w_m: usize,\n    codes: Buf,\n    out: Buf,\n}\nimpl Kernels {\n    fn launch_multi(&self, _s: &[Segment], _m: &[i32; 4], _x: &Buf, _acc: bool) {}\n}\nfn gemv_prequantized_multi(fns: &Kernels, x_quant: &Buf, segs_in: &[Segment], accumulate: bool) {\n    debug_assert!(segs_in.len() <= 4, \"multi-GEMV supports up to 4 segments\");\n    let mut segs: Vec<Segment> = segs_in.to_vec();\n    while segs.len() < 4 {\n        // m=0 pads match no rows — their pointers are never dereferenced\n        segs.push(segs[0].clone()); // reuse segment 0's pointers\n    }\n    let m: [i32; 4] = segs.iter().map(|s| s.w_m as i32).collect::<Vec<_>>().try_into().unwrap();\n    fns.launch_multi(&segs, &m, x_quant, accumulate); // ONE launch: the tiny\n} // m rows ride along with the big rows at ~zero marginal launch cost".to_string(),
        },
        // ── pre-gate-recovery-by-division-cancels-algebraically ── distilled
        // from the measured-GOAT katgpt-rs Issue 460 fix (riir-train
        // Issue 460 / Bench 475; commit e2853fbf, 2026-08-18): the MLA
        // backward reconstructed the pre-gate attention output as
        // `attn_out_gated / gate` — `gate = sigmoid(W_g · h)` underflows
        // to a HARD ZERO in f32 once the pre-activation drops below ~-88,
        // and the reconstruction is 0/0 = NaN. Silent in the forward (a
        // saturated gate is finite, the gated output is just 0) and common
        // (4 of 10 real sequences at random init, 4 of 5 seeds); it
        // surfaced far from the cause as an opaque NsInvSqrtFailed in the
        // optimizer. Localization proof: the FIRST corrupt tensor was
        // `mla.w_g` — the ONLY consumer of the reconstructed value; every
        // other MLA grad reads `attn_out_gated` and stayed clean. Fix:
        // `gated == pre * g` by construction, so `pre * g * (1-g) ==
        // gated * (1-g)` — the division disappears with no epsilon,
        // bit-identical wherever the old form was finite; the public
        // `saved.attn_out` reconstruction is guarded to 0.0 where g == 0
        // (the pre-gate value is information-theoretically unrecoverable
        // there — gated is 0 too), and the checkpoint path SAVES the true
        // value instead of dividing it back out. Bench 475 repro: 6/10 ->
        // 10/10 usable backward passes; all 6 finite-difference gradient
        // checks still pass.
        //
        // Distinct from saturating-nonlinearity-recovery-breaks-near-cap
        // (B35 — the DERIVATIVE recovered from a cached output rounds to
        // exactly 0 near cap, a dead gradient, fixed by raw-argument
        // recompute; this is a VALUE reconstruction by DIVISION producing
        // 0/0 NaN, fixed by algebraic elimination — the factor cancels, no
        // recompute), from sigmoid-deriv-recovered-from-output (B32b — the
        // optimization family this rule makes singular-free), and from
        // sign-branch-stable-sigmoid (B32a — forward sigmoid computation
        // hygiene; this is backward reconstruction discipline).
        KernelRule {
            rule_id: "pre-gate-recovery-by-division-cancels-algebraically".to_string(),
            gpu_concept: "A backward pass that needs the pre-gate activation of a multiplicative gate (gated = g * x_pre with g = sigmoid(W_g . h)) must never reconstruct it by dividing the saved gated output by the gate: sigmoid underflows to a HARD ZERO in f32 once the pre-activation drops below ~-88, the reconstruction is then 0/0 = NaN, and the failure is doubly hidden — the forward stays perfectly normal (a saturated gate is finite; the gated output is simply 0) and the NaN surfaces far from its cause as an opaque optimizer failure steps later. The division is also unnecessary: every gradient consumer of the pre-gate value multiplies it by gate-derived factors, and gated == pre * g by construction, so the g cancels — the gate's own weight grad d_gate_pre = d_gated * pre * g * (1 - g) rewrites as d_gated * gated * (1 - g): bit-identical wherever the old form was finite, no epsilon, no clamp, one fewer divide per element. Where the gate is exactly 0 the pre-gate value is information-theoretically unrecoverable (gated is 0 too — 0/0 carries no information), so a public reconstruction field reports a guarded 0.0 instead of poisoning callers, and the checkpoint path SAVES the true pre-gate value rather than dividing it back out. Detection tell: the gradient NaN localizes to the single weight matrix that consumes the reconstructed value while every gradient reading the post-gate value stays clean — that asymmetry is the proof. Distinct from saturating-nonlinearity-recovery-breaks-near-cap (the derivative recovered from a cached output rounds to exactly 0 near cap — a dead gradient, fixed by recomputing the raw argument; this is a value reconstruction by division producing NaN — fixed by algebraic elimination, the factor cancels with no recompute), from sigmoid-deriv-recovered-from-output (the recovery optimization family this rule makes singular-free), and from sign-branch-stable-sigmoid (forward sigmoid computation hygiene — this is backward reconstruction discipline).".to_string(),
            ref_shape: "// naive: backward reconstructs the pre-gate activation by DIVIDING the\n// saved gated output by the gate — singular exactly at saturation, and\n// silent: the forward stays finite (gated is just 0 where g underflowed)\nfn gate_backward_naive(d_gated: &[f32], gated: &[f32], gate: &[f32],\n                       h: &[f32], d_w_g: &mut [f32]) {\n    let mut pre = vec![0.0f32; gated.len()];\n    for i in 0..gated.len() {\n        // gate = sigmoid(W_g . h) underflows to a HARD ZERO in f32 below\n        // ~-88 pre-activation; gated[i] is 0 there too\n        pre[i] = gated[i] / gate[i]; // 0/0 = NaN — poisons every consumer\n    }\n    for i in 0..gated.len() {\n        // the gate's weight grad is the ONLY consumer of the reconstruction\n        let d_gate_pre = d_gated[i] * pre[i] * gate[i] * (1.0 - gate[i]);\n        for (k, &hk) in h.iter().enumerate() {\n            d_w_g[k] += d_gate_pre * hk; // NaN lands in ONE matrix, then\n        } // spreads step-later as an opaque optimizer failure\n    }\n}".to_string(),
            opt_pattern: "// optimized: gated == pre * g by construction, so the g cancels in every\n// gradient consumer — the reconstruction (and its division) disappears\nfn gate_backward_cancelled(d_gated: &[f32], gated: &[f32], gate: &[f32],\n                           h: &[f32], d_w_g: &mut [f32]) {\n    for i in 0..gated.len() {\n        let g = gate[i];\n        // d_gated * pre * g * (1-g) == d_gated * (pre * g) * (1-g)\n        let d_gate_pre = d_gated[i] * gated[i] * (1.0 - g); // g == 0 gives\n        // exactly 0.0, never NaN — bit-identical where the old form was finite\n        for (k, &hk) in h.iter().enumerate() {\n            d_w_g[k] += d_gate_pre * hk;\n        }\n    }\n}\n// a public pre-gate reconstruction, if one must exist, is guarded: where\n// g == 0 the pre-gate value is information-theoretically unrecoverable\n// (gated is 0 too — 0/0 carries no information) — report 0.0, and SAVE\n// the true value at the checkpoint boundary instead of dividing it out\nfn pre_gate_reconstruct_guarded(gated: &[f32], gate: &[f32]) -> Vec<f32> {\n    (0..gated.len())\n        .map(|i| if gate[i] > 0.0 { gated[i] / gate[i] } else { 0.0 })\n        .collect()\n}".to_string(),
        },
        // ── same-input-gemv-weight-concat-at-upload ── distilled from the
        // CubeCL decode-forward (ternary_deltanet_gpu_forward.rs Issue 642
        // F3/F2 + Issue 648 F9): N GEMV projections sharing one input vector
        // (qkv+z+a+b; gate+up; Wk+Wv) merged by baking the weight
        // CONCATENATION into the upload (TernaryHandle::from_weights_concat /
        // from_two_weights) — the STOCK kernel dispatches the merged GEMV
        // with no bespoke fusion kernel and no segment-launcher support.
        // The substrate-constrained third branch of the same-input-merge
        // family (B58's segments rule needs a multi-segment launcher API;
        // B15's fuse-gate-up needs a bespoke kernel; this needs only frozen
        // weights). Two consumer variants in-source: offset-consuming (K+V
        // at [0..kvd]/[kvd..2kvd], gate+up read by the concat SwiGLU) =
        // zero extra dispatches; separate-buffer consumers pay ONE split
        // kernel (Split4) — still 4 GEMVs -> 2 dispatches.
        KernelRule {
            rule_id: "same-input-gemv-weight-concat-at-upload".to_string(),
            gpu_concept: "When several GEMV projections consume the SAME input vector, one launch each pins every projection to the kernel-latency floor; when the substrate's kernel has NO multi-segment launcher (the B58 segments route) and a bespoke fused kernel is not justified (the B15 route), vertical weight concatenation merges them anyway: [Wa; Wb] . x == [Wa . x; Wb . x] exactly, so bake the concat into the WEIGHT LAYOUT at upload time and dispatch one STOCK GEMV over the concatenated matrix. Consumers split into two shapes: offset-consumers read their slice of the one contiguous output at a compile-time offset (K at [0..kvd], V at [kvd..2kvd]; gate at [0..mlp], up at [mlp..2mlp]) for ZERO extra dispatches; separate-buffer consumers get ONE split kernel copying regions out — still N launches -> 2. Constraints: weights frozen (a weight change re-concats — hot-swap substrates keep separate handles, B25's keep-caches-alive applies); output rows must share dtype/quant format (the concat is layout-level). Measured in-source: 4 GEMVs -> 1 GEMV + 1 split saves 2 dispatches per DeltaNet layer; K+V and gate+up variants save the split too. Distinct from same-input-gemv-segments-single-launch (launch-time segment table with separate outputs, no weight transformation, mutable weights fine — that needs a segment-supporting kernel API, this needs none) and from fuse-gate-up-gemv-activation (bespoke fused kernel with in-kernel activation vs stock kernel + layout).".to_string(),
            ref_shape: "// naive: N same-input projections = N launches at the latency floor\nstruct Kernels;\nstruct Handle { m: usize }\nimpl Kernels {\n    fn launch_gemv(&self, _w: &Handle, _x: &[f32], _out: &mut [f32]) {}\n}\nfn project_naive(k: &Kernels, w_qkv: &Handle, w_z: &Handle, w_a: &Handle,\n                 w_b: &Handle, x: &[f32], qkv: &mut [f32], z: &mut [f32],\n                 a: &mut [f32], b: &mut [f32]) {\n    k.launch_gemv(w_qkv, x, qkv); // ~5.6 us kernel-latency floor EACH\n    k.launch_gemv(w_z, x, z);     // the tiny projections pay full launch\n    k.launch_gemv(w_a, x, a);\n    k.launch_gemv(w_b, x, b);\n} // 4 launches for 1 input: overhead dominates small rows".to_string(),
            opt_pattern: "// optimized: concat the WEIGHTS at upload; ONE stock-GEMV launch; consumers\n// either read at compile-time offsets (zero extra dispatches) or pay ONE\n// split kernel (still 4 -> 2)\nstruct Kernels;\nstruct Handle { m: usize }\nimpl Kernels {\n    fn launch_gemv(&self, _w: &Handle, _x: &[f32], _out: &mut [f32]) {}\n    fn split4(&self, _src: &[f32], _outs: [&mut [f32]; 4]) {}\n}\nfn concat_upload(_w: &[&Handle]) -> Handle { Handle { m: 0 } } // once at freeze\nfn project_concat(k: &Kernels, w_concat: &Handle, x: &[f32],\n                  scratch: &mut [f32], qkv: &mut [f32], z: &mut [f32],\n                  a: &mut [f32], b: &mut [f32]) {\n    k.launch_gemv(w_concat, x, scratch); // ONE launch over [Wqkv; Wz; Wa; Wb]\n    k.split4(scratch, [qkv, z, a, b]);   // ONE split — separate buffers\n} // offset-consumers (K@0, V@kvd; gate@0, up@mlp) skip even the split".to_string(),
        },
        // ── deferred-residual-fused-into-next-layer-norm ── distilled from
        // the CubeCL decode-forward layer loop (Issue 645 T3): the post-FFN
        // residual add is NOT dispatched at the end of its layer — it is
        // DEFERRED across the loop boundary and absorbed by the NEXT
        // iteration's already-fused ResidualAddRmsNorm kernel; the first
        // layer uses standalone RMSNorm (no predecessor) and the LAST
        // layer's deferred add runs standalone after the loop. -63
        // dispatches/token at n_layer=64 with zero new kernels. The file
        // documents the composition ladder: producer-side fusion into the
        // down-GEMV (writing self.x directly — the B19 route) beats the
        // deferral when available and disables it.
        KernelRule {
            rule_id: "deferred-residual-fused-into-next-layer-norm".to_string(),
            gpu_concept: "An elementwise op whose only consumer sits at the START of the NEXT loop iteration should not be dispatched at the end of its producer's iteration: hold the value in the producer's output buffer, skip the dispatch, and let the next iteration's entry kernel — which already fuses this op with its own first op (a ResidualAdd+RMSNorm kernel) — absorb both operands in one launch. Three structural pieces: the first iteration special-cases to the un-fused entry kernel (no predecessor residual exists); the loop TAIL applies the last iteration's deferred op standalone (no successor exists to absorb it); and the composition ladder — when the producer itself can fuse the op in-place (a GEMV writing its output directly onto the residual buffer), producer-side fusion wins and the deferral collapses to the plain path. The scheduling analog of defer-readback-until-after-submit: that defers a TIMING (a download) past a boundary; this defers a whole DISPATCH across an iteration boundary to reach a fusion site. Distinct from fuse-add-rms-norm (a KERNEL fusion of two adjacent passes at one site — this DEFERS a dispatch across an iteration boundary, requiring tail fixup + first-iteration special case + no new kernel) and from fuse-residual-via-in-place-output-array (producer-side in-place fusion INSIDE one kernel — the ladder's better rung, which this rule falls back from).".to_string(),
            ref_shape: "// naive: every layer boundary pays a standalone residual-add dispatch\nstruct Kernels;\nimpl Kernels {\n    fn rmsnorm(&self, _x: &mut [f32]) {}\n    fn residual_add(&self, _a: &mut [f32], _b: &[f32]) {}\n    fn layer_body(&self, _x: &mut [f32], _ffn_out: &mut [f32]) {}\n}\nfn layer_loop_naive(k: &Kernels, x: &mut [f32], ffn_out: &mut [f32],\n                    n_layers: usize) {\n    for _ in 0..n_layers {\n        k.rmsnorm(x);\n        k.layer_body(x, ffn_out);\n        k.residual_add(x, ffn_out); // dispatched EVERY boundary: 64 extra\n    } // launches/token — but its only consumer is the NEXT layer's norm!\n}".to_string(),
            opt_pattern: "// optimized: defer the add across the boundary; the next iteration's\n// FUSED add+norm kernel absorbs it — tail applies the last one standalone\nstruct Kernels;\nimpl Kernels {\n    fn rmsnorm(&self, _x: &mut [f32]) {}\n    fn residual_add_rmsnorm_fused(&self, _x: &mut [f32], _res: &[f32]) {}\n    fn residual_add(&self, _a: &mut [f32], _b: &[f32]) {}\n    fn layer_body(&self, _x: &mut [f32], _ffn_out: &mut [f32]) {}\n}\nfn layer_loop_deferred(k: &Kernels, x: &mut [f32], ffn_out: &mut [f32],\n                       n_layers: usize) {\n    k.rmsnorm(x); // layer 0: no predecessor residual — plain entry\n    k.layer_body(x, ffn_out);\n    for _ in 1..n_layers {\n        // the PREVIOUS layer's ffn_out is absorbed HERE — one fused kernel\n        k.residual_add_rmsnorm_fused(x, ffn_out); // add(prev deferred) + norm\n        k.layer_body(x, ffn_out); // leaves ffn_out un-added for the next one\n    }\n    k.residual_add(x, ffn_out); // tail: the LAST deferred add, standalone\n} // n_layers-1 add dispatches eliminated; zero new kernels".to_string(),
        },
        // ── reset-state-in-place-fill-never-realloc ── distilled from the
        // CubeCL decode-forward reset_state (Plan 528 T0.2 blocker): the
        // previous implementation called create_from_slice for each of 128
        // persistent buffers per reset, fragmenting the dynamic memory pool
        // until the Go arena consumer (independent prompts per move) hit
        // SIGKILL. The fix keeps buffer identity fixed for the process
        // lifetime and resets CONTENT with one in-place zero-fill kernel
        // per buffer; caches whose consumers bound reads by position (the
        // KV cache reads only [0..=pos]) skip even that — reset = pos = 0.
        // The pool-churn failure recurs 3x in this file alone.
        KernelRule {
            rule_id: "reset-state-in-place-fill-never-realloc".to_string(),
            gpu_concept: "A sequence/state reset must never rebuild state by re-allocating + re-uploading persistent buffers: each create_from_slice carves a NEW slice from the dynamic pool while the old slice's lifetime drains, so a high-churn consumer (independent prompts per move, per-request resets) fragments the pool until allocation fails hard (measured: SIGKILL under the Go arena at 128 buffers per reset). Fix: persistent buffer identity is a process-lifetime property — reset CONTENT with an in-place zero-fill kernel per buffer (one dispatch, no allocation, no upload), and for caches whose consumers bound reads by a position cursor (a KV cache read only at [0..=pos]), skip the zero-fill entirely: resetting the CURSOR to 0 subsumes the content reset because stale entries past the new pos are never read (the bounded-read principle of write-before-read-state-skips-checkpoint, applied at the reset boundary instead of the checkpoint boundary). Distinct from persistent-zeros-source-encoder-copy-clear (clearing accumulators between dispatches INSIDE one encoder build — an ordering hazard) and from append-cache-rewind-overwrite-in-place (pointer rollback for RE-EXECUTION of the same sequence vs full-content zeroing for a FRESH sequence).".to_string(),
            ref_shape: "// naive: reset = re-allocate + re-upload every persistent buffer\nstruct Client;\nstruct Buf;\nimpl Client {\n    fn create_from_slice(&self, _v: &[f32]) -> Buf { Buf }\n    fn fill_zeros(&self, _b: &mut Buf) {}\n}\nstruct State { bufs: Vec<Buf>, pos: usize }\nimpl State {\n    fn reset_naive(&mut self, c: &Client) {\n        // 128x per reset: a NEW pool slice each call while the old slices\n        // drain — a prompt-per-move consumer fragments the pool to SIGKILL\n        self.bufs = (0..self.bufs.len())\n            .map(|_| c.create_from_slice(&[0.0; 0]))\n            .collect();\n        self.pos = 0;\n    }\n}".to_string(),
            opt_pattern: "// optimized: identity is process-lifetime; reset CONTENT in place; caches\n// whose reads are cursor-bounded skip even the fill\nstruct Client;\nstruct Buf;\nimpl Client {\n    fn create_from_slice(&self, _v: &[f32]) -> Buf { Buf }\n    fn fill_zeros(&self, _b: &mut Buf) {}\n}\nstruct State { bufs: Vec<Buf>, kv: Buf, pos: usize }\nimpl State {\n    fn reset_in_place(&mut self, c: &Client) {\n        for b in &mut self.bufs {\n            c.fill_zeros(b); // ONE dispatch per buffer: no alloc, no upload\n        }\n        // KV cache: consumers read only [0..=pos] — pos = 0 subsumes the\n        // content reset; stale entries past it are never read\n        self.pos = 0;\n        let _ = &self.kv;\n    }\n}".to_string(),
        },
        // ── barrier-free-per-dependency-wait-from-loop-counters ── distilled
        // from arXiv:2608.13757 §5 (Sung, Shyamsunder, Zhang, Kroening,
        // Choi — "A Barrier-Free Synchronization Algorithm for Multi-Engine
        // AI Accelerators", CGO '27; Amazon + Cornell; Lean 4 bisimulation
        // ~15K lines 0 admitted; measured on real Trainium 2): loops over
        // heterogeneous workers with cross-iteration dependencies must not
        // drain+handshake+reset ALL workers at iteration boundaries — track
        // a monotone entry counter per worker/loop and compute each
        // dependency's wait threshold in closed form (Eq 1 -> the §5.2
        // three allocatable cases: producer-in-S -> r_P - k; producer
        // nested forward offset-0 / backward offset-1 -> r_P; the
        // underflowed target is a no-wait). Measured: 10-45% latency cut
        // across production NKI kernels, 3.3x on the sync-bound AddManyLoop
        // microbenchmark (norm-lat 0.30 — every barrier was pure overhead
        // there). Honest applicability: wgpu/CubeCL/Metal host APIs expose
        // no fine-grained semaphore — the live surfaces are cudarc CUDA
        // events + multi-stream (cudaStreamWaitEvent IS a per-dependency
        // wait), host orchestration loops over pipeline stages, and
        // multi-threaded worker loops. The rule encodes the MECHANISM; the
        // 3.3x is Trainium-specific source evidence.
        //
        // Distinct from chain-dispatches-single-sync-point (B19 — acyclic
        // straight-line with ONE end sync; no loops, no counters), from
        // expert-loop-two-phase-split-batch-across-iterations (B40 —
        // RESTRUCTURES the loop into two batched phases; this computes the
        // exact per-dependency moment with no restructuring), from
        // sibling-dispatches-before-any-readback (B36 — queue ORDERING of
        // independent work; no thresholds), from mid-pipeline-device-alloc-
        // is-implicit-sync (B58 — a hidden sync to AVOID; this is a
        // computed wait to INSTALL), and from the intra-kernel smem barrier
        // family (smem-slot-role-reversal-needs-barrier marks barriers that
        // can NEVER be removed within a workgroup — this removes INTER-
        // worker barriers between separately-scheduled workers).
        KernelRule {
            rule_id: "barrier-free-per-dependency-wait-from-loop-counters".to_string(),
            gpu_concept: "A loop nest of heterogeneous workers (engines, streams, threads) with cross-iteration dependencies must not synchronize by draining and handshaking every worker at every iteration boundary — the all-worker barrier serializes workers that share no dependency, prevents any run-ahead into the next iteration, and pays its drain+handshake+reset cost once per iteration even when the loop body has a single true cross-iteration edge. Instead give each worker a monotone entry count per loop (incremented at every entry, never reset) and compute each dependency's wait threshold in closed form from those counters at issue time: with the dependency carried at the shared loop S at offset k (the consumer at iteration i reads the producer's iteration i-k), a producer directly in S retires once per iteration so the threshold is r - k on the producer's monotone count; a producer nested in a sub-loop retires a variable number of times per outer trip, so only the forward (offset 0) and backward (offset 1) cases are closed-form — both threshold on r_P alone; the target underflows (r <= k) when no producer iteration is owed, a no-wait case; dependencies outside this subset (multi-level gaps, nested offsets greater than 1) must fall back to the barrier form rather than be mis-encoded. Every worker then stalls only for its actual dependencies — unrelated work on other workers overlaps freely, including across iteration boundaries and pre/post-loop work. Measured on real Trainium 2 across production NKI kernels (tiled matmul, RMSNorm, FlashAttention, AdamW, Dropless MoE): 10-45% latency reduction versus the barrier baseline, and 3.3x on a synchronization-bound microbenchmark where a no-dependency loop made every barrier pure overhead. Applicability: the mechanism ports to any orchestration with per-dependency waits — CUDA events between streams (cudaStreamWaitEvent IS a per-dependency wait), host poll loops over pipeline stages, multi-threaded worker loops; wgpu/CubeCL/Metal host APIs expose no fine-grained semaphore, so on those substrates the barrier analog is a per-iteration poll-join of all stages and the fixed form is a per-stage wait on the producer's monotone count. Distinct from chain-dispatches-single-sync-point (acyclic straight-line with one end sync — no loops, no counters), from expert-loop-two-phase-split-batch-across-iterations (restructures the loop into two batched phases — this computes the exact per-dependency moment with no restructuring), from sibling-dispatches-before-any-readback (queue ordering of independent work — no thresholds), from mid-pipeline-device-alloc-is-implicit-sync (a hidden sync to avoid — this is a computed wait to install), and from the intra-kernel smem barrier family (those mark barriers that can never be removed within a workgroup — this removes inter-worker barriers between separately-scheduled workers).".to_string(),
            ref_shape: "// naive: an all-worker barrier at EVERY iteration boundary — every worker\n// drains + handshakes + resets, even though only ONE cross-iteration\n// dependency exists (consumer iter i reads producer iter i-2); the\n// unrelated worker C is serialized for no reason at all\nstruct Barrier;\nimpl Barrier {\n    fn wait(&self) {} // drains every in-flight worker, handshake, reset\n}\nfn launch_a(_i: usize) {}\nfn launch_b(_i: usize) {}\nfn launch_c(_i: usize) {}\nfn pipeline_barriers(n_iters: usize, barrier: &Barrier) {\n    for i in 0..n_iters {\n        launch_a(i); // worker A: producer\n        launch_c(i); // worker C: NO dependency on anyone — still fenced\n        barrier.wait(); // iteration boundary: nobody may run ahead\n        if i >= 2 {\n            launch_b(i); // worker B: consumes A's iteration i-2\n        }\n        barrier.wait(); // end-of-iteration drain AGAIN — pure overhead\n    }\n}".to_string(),
            opt_pattern: "// optimized: each worker keeps a MONOTONE entry count; the consumer\n// computes its dependency's threshold in closed form ((i+1) - k on the\n// producer's count) and waits per-dependency — worker C never syncs,\n// A runs ahead freely, iterations overlap\nstruct Counters {\n    a_done: std::sync::atomic::AtomicUsize, // producer retire count (r_P)\n}\nfn wait_ge(c: &std::sync::atomic::AtomicUsize, threshold: usize) {\n    // per-dependency wait: stalls THIS worker only\n    while c.load(std::sync::atomic::Ordering::Acquire) < threshold {\n        std::thread::yield_now();\n    }\n}\nfn launch_a(_i: usize) {}\nfn launch_b(_i: usize) {}\nfn launch_c(_i: usize) {}\nfn pipeline_barrier_free(n_iters: usize, k: usize, ct: &Counters) {\n    std::thread::scope(|s| {\n        s.spawn(|| {\n            for i in 0..n_iters {\n                launch_c(i); // unrelated worker: NEVER fenced\n            }\n        });\n        s.spawn(|| {\n            for i in 0..n_iters {\n                launch_a(i); // producer: retires once per iteration\n                ct.a_done.fetch_add(1, std::sync::atomic::Ordering::Release);\n            }\n        });\n        s.spawn(|| {\n            for i in 0..n_iters {\n                if i >= k {\n                    // closed form: consumer at r = i+1 needs the producer\n                    // through r - k, so the threshold is (i+1) - k entries\n                    wait_ge(&ct.a_done, (i + 1) - k);\n                }\n                launch_b(i); // else: target underflowed — no wait at all\n            }\n        });\n    });\n}\n// dependencies OUTSIDE the allocatable subset (multi-level gap, nested\n// offset > 1) fall back to the barrier form — never mis-encode them".to_string(),
        },
        // ── shared-counter-decode-producer-progress ── distilled from
        // arXiv:2608.13757 §5.5 + §6 (the per-loop allocation + the
        // semaphore-ALU tradeoff): one dedicated progress counter per
        // producer instruction does not scale (production loop nests have
        // thousands of bodies); share ONE counter per (loop, worker) and
        // DECODE per-producer progress in closed form — in-order retirement
        // keeps the N co-body counts within 1 of each other, so after the
        // K-th of N retires in iteration r the shared counter reads
        // N*r - (N - K) exactly (Eq 4/5). Decision content = the §6.1
        // granularity ladder (per-instruction O(N) counters / 3 ALU ops;
        // per-loop O(L*E) / 5; per-engine O(E) / O(D)), mixable per region,
        // with §6.2 LICM + CSE cutting the ALU cost without touching
        // correctness.
        //
        // The arithmetic complement of barrier-free-per-dependency-wait-
        // from-loop-counters (THAT computes WHEN to wait from loop-entry
        // counters; THIS recovers WHO retired from a shared counter's
        // value — they compose: the closed-form threshold feeds this
        // decode, Eq 5).
        KernelRule {
            rule_id: "shared-counter-decode-producer-progress".to_string(),
            gpu_concept: "One dedicated progress counter per producer instruction does not scale — a production loop nest has thousands of bodies, and per-producer atomics or semaphores cost O(N) shared resources. Instead share ONE counter per (loop, worker): every retirement in the body increments it, and the per-producer retirement count is DECODED in closed form — in-order retirement keeps the N co-body instructions' counts within 1 of each other (the first K at m+1, the rest at m), so after the K-th of N instructions retires in iteration r the shared counter reads exactly N*r - (N - K), and 'producer at position K has retired at least r times' is precisely 'counter >= N*r - (N - K)'. The per-loop check adds two operations over the dedicated-counter form (the N* scaling and the -(N - K) offset) for five ALU ops per issue. The decision content is the granularity ladder: per-instruction (O(N) counters, 3 ALU ops per issue — the counter IS the progress, no decode), per-loop (O(L*E) counters for L loops and E engines, 5 ALU ops per issue — this decode), and per-engine (O(E) counters, O(D) ALU ops per issue for the D loops on the producer's path — the decode sums each path loop's contribution: the full-body term for loops that ran to completion before the producer, the precise parent-loop term for the producer's own loop). Each step down in counter count pushes more of the recovery onto runtime ALU, and the points are MIXABLE per region under a tight resource budget (per-loop where the dependency footprint is small, per-engine for deeply nested regions). Standard compiler passes then cut the ALU cost without affecting correctness: LICM hoists each loop's contribution out of deeper nests — it changes only when that loop is re-entered — leaving the innermost contribution plus a cached outer partial sum in steady state; CSE shares the mask computation and partial sums across consumers with a common ancestor. Empirical resource shape on Trainium 2: registers stay O(L) (4 per engine for single-loop kernels, 8-11 for 2-3 loop nests), counters 4-19 across the benchmark suite. Distinct from barrier-free-per-dependency-wait-from-loop-counters (the sibling rule computes WHEN to wait from loop-entry counters — this recovers WHO retired from a shared counter's value; they compose, the closed-form threshold feeding this decode) — no other corpus rule decodes a shared counter for producer progress (dedup-audited at pool time and re-verified at batch time).".to_string(),
            ref_shape: "// naive: one dedicated atomic per producer — the count IS the progress,\n// no decode needed, but the shared-resource cost scales with instruction\n// count: every producer in every loop body owns a counter forever\nstruct PerProducer {\n    prod1: std::sync::atomic::AtomicUsize,\n    prod2: std::sync::atomic::AtomicUsize,\n    prod3: std::sync::atomic::AtomicUsize, // ... one per body instruction:\n} // a production loop nest cannot afford O(N) shared counters\nfn body_retire(_c: &PerProducer, _which: usize) {}\nfn wait_prod2_naive(c: &PerProducer, r: usize) {\n    // dedicated counter reads retirements directly — but this shape is why\n    // the resource bill multiplies by instruction count\n    while c.prod2.load(std::sync::atomic::Ordering::Acquire) < r {\n        std::thread::yield_now();\n    }\n}".to_string(),
            opt_pattern: "// optimized: ONE shared counter per (loop, worker) + closed-form decode —\n// in-order retirement keeps the N co-body counts within 1 of each other,\n// so after the K-th of N retires in iteration r the counter reads\n// N*r - (N - K); \"producer K retired >= r times\" <=> counter >= that\nstruct Shared(std::sync::atomic::AtomicUsize);\nfn wait_producer_k(c: &Shared, r: usize, n: usize, pos: usize) {\n    // n = body instruction count on this worker, pos = producer position\n    let threshold = n * r - (n - pos);\n    while c.0.load(std::sync::atomic::Ordering::Acquire) < threshold {\n        std::thread::yield_now();\n    }\n}\n// The granularity ladder (mixable per region under a resource budget):\n//   per-instruction: O(N) counters,   3 ALU ops/issue (counter == progress)\n//   per-loop:        O(L*E) counters, 5 ALU ops/issue (this decode)\n//   per-engine:      O(E) counters,   O(D) ALU ops/issue (sums every path\n//     loop's term: full-body for completed loops, precise for the parent)\n// LICM hoists each loop's term out of deeper nests (it changes only on\n// re-entry); CSE shares masks + partial sums across sibling consumers.".to_string(),
        },
        // ── masked-branchless-wait-collapse ── distilled from
        // arXiv:2608.13757 §5.3 (Eq 2): the dependency-satisfaction
        // condition is a DISJUNCTION (no-wait OR counter >= threshold)
        // but a wait primitive takes a single threshold — collapse it
        // with a multiplicative 0/1 mask (isGT(trip, offset) * expr),
        // a fixed three-op sequence with no branch on the issue path.
        // The branchless-select mechanism class applied to a
        // synchronization predicate.
        //
        // Distinct from branchless-select (same ALU family, different
        // operand: a DATA select inside a compute kernel vs a sync
        // predicate feeding a wait primitive). Composes with the two
        // sibling batch-70 rules: the closed-form threshold is the expr
        // this rule masks; the shared-counter decode's N*r - (N - K) is
        // the masked threshold in the per-loop allocation (Eq 5).
        KernelRule {
            rule_id: "masked-branchless-wait-collapse".to_string(),
            gpu_concept: "A wait primitive that takes a single threshold cannot consume a disjunctive condition — 'no producer is owed OR the counter has reached the threshold' — so the naive shape branches on the no-wait arm before every wait, putting a data-dependent branch on the issue path of every consumer exactly where the worker is about to stall anyway. Collapse the disjunction with a multiplicative 0/1 mask: mask = is_gt(trip_count, offset) materialized as an integer (1 iff a producer iteration is owed, 0 when the target iteration underflowed), wait_val = mask * threshold, and the single check 'counter >= wait_val' is equivalent to the full disjunction — when nothing is owed wait_val is 0 and any non-negative counter passes immediately. The emitted sequence is fixed at three operations (compute the mask, compute the threshold expression, multiply) with no branch, the branchless-select mechanism applied to a synchronization predicate. Elision composes: when every dependency at a loop has offset 0 the no-wait arm is never taken (the loop was entered, so the trip count is at least 1) and the trip counter and mask elide entirely — wait_val is just the expression. Regime honesty: the collapse pays where the wait path is hot and the primitive truly takes one register threshold; on a host API that natively offers wait-or-skip semantics the branch form is equivalent, and the mask costs three ALU ops per issue that a branch predictor might otherwise hide — encode it where the issue path is measured hot. Distinct from branchless-select (the same ALU mechanism on a data select inside a compute kernel — this collapses a synchronization predicate feeding a wait primitive) and from the rust_perf branchless family (a different domain corpus: those remove data branches in hot loops; this removes the branch guarding a wait). Composes with barrier-free-per-dependency-wait-from-loop-counters (the closed-form threshold is the expression this rule masks) and shared-counter-decode-producer-progress (the decoded threshold is the masked operand in the per-loop allocation).".to_string(),
            ref_shape: "// naive: the wait condition is a DISJUNCTION — no producer owed (the\n// target iteration underflowed) OR counter >= threshold — so a branch\n// guards every wait on the issue path of every consumer\nfn wait_or_skip_naive(counter: &std::sync::atomic::AtomicUsize,\n                      trip: usize, offset: usize, threshold: usize) {\n    if trip <= offset {\n        return; // branch #1: no producer owed — skip the wait entirely\n    }\n    // the branchy guard is re-evaluated per consumer issue, on the path\n    // where the worker is about to stall anyway\n    while counter.load(std::sync::atomic::Ordering::Acquire) < threshold {\n        std::thread::yield_now();\n    }\n}".to_string(),
            opt_pattern: "// optimized: collapse the disjunction into ONE threshold via a\n// multiplicative 0/1 mask — three fixed ops, no branch on the issue path\nfn is_gt(a: usize, b: usize) -> usize {\n    (a > b) as usize // boolean materialized as a 0/1 integer\n}\nfn wait_masked(counter: &std::sync::atomic::AtomicUsize,\n               trip: usize, offset: usize, expr: usize) {\n    let mask = is_gt(trip, offset); // 1 iff a producer iteration is owed\n    let wait_val = mask * expr;     // 0 when nothing is owed\n    // the single check == the full disjunction: wait_val = 0 passes any\n    // non-negative counter immediately; wait_val = expr is the real gate\n    while counter.load(std::sync::atomic::Ordering::Acquire) < wait_val {\n        std::thread::yield_now();\n    }\n}\n// elision: when every dependency at a loop has offset 0, the no-wait arm\n// is never taken (the loop was entered, so trip >= 1) — the trip counter\n// and the mask elide entirely and wait_val is just the expression".to_string(),
        },

        // ── rotated-ring-undo-via-rebind-reference-snapshot ── distilled
        // from oMLX patches/mlx_lm_mtp/cache_rollback.py (Batch 71 /
        // Research 083; source re-verified at 2026-08-24 mine time): a
        // ROTATED ring cache cannot trim — the evicted token's slot is
        // overwritten, so a rejected speculative verify leaves PHANTOM
        // tokens that progressively corrupt output ("hit on
        // DeepSeek-V4-Flash, sliding_window=128"). The multi-token verify
        // takes the _update_concat path which "only rebinds keys/values
        // (no in-place setitem), so stashing the pre-update attribute
        // references plus the update's inputs gives an exact undo";
        // "trim(rejected) then restores the snapshot and replays the
        // confirmed/accepted prefix"; arming is thread-local around the
        // MTP backbone forward only; the v + 0 detach ("a plain reference
        // would see the post-update value") covers paths that may mutate
        // in place — plain refs suffice on the rebind-only path.
        KernelRule {
            rule_id: "rotated-ring-undo-via-rebind-reference-snapshot".to_string(),
            gpu_concept: "A rotated ring cache (a sliding-window KV cache over a circular buffer) cannot trim to undo a rejected speculative verify: once the ring has wrapped, the evicted token's slot has been overwritten, so the rejected draft positions cannot be discarded exactly — the stale token persists as a phantom that every later window read sees, progressively corrupting output (field hit: DeepSeek-V4-Flash at sliding_window=128). Pointer rewind is structurally impossible here — append-cache-rewind's monotone extent does not exist in the rotated regime. The exact undo instead exploits the update path's contract: a multi-token (S>=2) verify update takes the concat path, which only rebinds the keys/values attributes (never in-place setitem), so stashing the pre-update attribute references PLUS the update's staged inputs gives a complete undo — on rejection, restore the references and replay the confirmed prefix through the ordinary update as a decode-sized step. Snapshot discipline is path-dependent: on a rebind-only path the old wrappers are never mutated, so plain references suffice (a refcount bump — no copy); where the underlying path may mutate in place, a plain reference would alias the post-update state and a detach-copy is required instead. Arm the stash only around the speculative forward (a thread-local flag the caller sets) so non-speculative flows keep stock trim semantics, and chain single-step decode-consistent verifies by keeping the original snapshot and concatenating the newly staged inputs. The undo log also makes is_trimmable return true for the armed cache, routing rejection through restore+replay instead of the impossible physical trim. Distinct from append-cache-rewind-overwrite-in-place (the NON-rotated append-only regime — pointer rewind on a monotone extent; the rotated regime is structurally un-rewindable, which is why this rule exists), from write-before-read-state-skips-checkpoint (decides the checkpoint SET need not include write-before-read caches — this decides the undo MECHANISM when exact discard is impossible), from make-unmake-over-clone-per-candidate (host game-state delta log, not device cache state), and from activation-checkpoint-as-handle-clone-deferred-batch-readback (checkpoint medium for backward training — this is inference-time speculative rollback).".to_string(),
            ref_shape: "// naive: a rotated ring cache (circular sliding window) with a plain\n// trim() — a rejected speculative verify tries to discard the draft tail\nstruct Ring {\n    keys: Vec<f32>,\n    values: Vec<f32>,\n    offset: usize, // ring write cursor: token t lands at (t % window)\n}\nimpl Ring {\n    fn update_in_place(&mut self, _k: &[f32], _v: &[f32]) {\n        // wraps: writing token t overwrites the slot of the evicted token\n        // t - window — once rotated, the evicted slot is GONE\n        self.offset = self.offset.wrapping_add(1);\n    }\n    fn trim(&mut self, n: usize) -> usize {\n        // physical trim: IMPOSSIBLE on a rotated ring — the rejected\n        // tokens' slots may already be overwritten; returning 0 leaves\n        // them as PHANTOMS every later window read sees\n        let _ = n;\n        0\n    }\n}\nfn verify_naive(ring: &mut Ring, draft_k: &[&[f32]], draft_v: &[&[f32]], accepted: usize) {\n    for (k, v) in draft_k.iter().zip(draft_v.iter()) {\n        ring.update_in_place(k, v); // speculatively append ALL draft tokens\n    }\n    let rejected = draft_k.len() - accepted;\n    ring.trim(rejected); // silent no-op: phantom tokens persist + corrupt\n}".to_string(),
            opt_pattern: "// optimized: undo log on the update path's REBIND contract — stash the\n// pre-update attribute refs + the staged inputs; rejection restores the\n// refs and REPLAYS the accepted prefix through the ordinary update\n#[derive(Clone)]\nstruct Arr; // device array wrapper (cheap refcount clone)\nstruct Ring2 {\n    keys: Arr,\n    values: Arr,\n    offset: usize,\n    undo: Option<((Arr, Arr, usize), (Arr, Arr))>, // (pre-refs, staged in)\n}\nthread_local! {\n    static ARMED: bool = false; // armed ONLY around the speculative forward\n}\nimpl Ring2 {\n    fn update_rebind(&mut self, k: &Arr, v: &Arr) {\n        // S>=2 verify takes the concat path: REBINDS attributes only,\n        // never in-place setitem — plain refs suffice for the snapshot\n        // (a path that may setitem in place needs a detach-copy instead)\n        if ARMED.with(|a| *a) {\n            self.undo = Some((\n                (self.keys.clone(), self.values.clone(), self.offset),\n                (k.clone(), v.clone()),\n            ));\n        }\n        let _ = (&self.keys, &self.values); // ... orig concat + window trim\n    }\n    fn trim_rejected(&mut self, staged_len: usize, rejected: usize) -> usize {\n        let Some((refs, staged)) = self.undo.take() else { return 0 };\n        let kept = staged_len - rejected; // accepted prefix length\n        self.keys = refs.0; // restore pre-update references — exact undo\n        self.values = refs.1;\n        self.offset = refs.2;\n        if kept > 0 {\n            let (k, v) = staged;\n            self.update_rebind(&k, &v); // replay the confirmed prefix as a\n        } // decode-sized ordinary update\n        rejected\n    }\n}".to_string(),
        },

        // ── gpu-api-thread-affinity-snapshot-metrics ── distilled from
        // oMLX process_memory_enforcer.py (Batch 71 / Research 083; read
        // in full 2026-08-24 — the Research 082 B-grade promoted to
        // source-verified, with pool-clear-waits-for-async-completion-
        // callbacks merged in as the justification for the flag-and-defer
        // shape): "During active requests this must not call MLX/Metal
        // APIs from the background enforcer thread. The scheduler records
        // the last mx.get_active_memory() sample on the MLX executor
        // thread; the enforcer combines that cached value with the kernel
        // phys_footprint ledger"; "Routes the reclaim through the
        // scheduler's shipped, lock-protected, engine-stream-synchronized
        // _sync_and_clear_cache path ... instead of touching Metal from
        // the enforcer thread — the enforcer must never touch Metal
        // directly. Setting the per-scheduler flag is GIL-atomic; the
        // actual clear fires on the inference thread at the next step
        // boundary, even under load"; "Reading the Apple default cap
        // falls back to mx.device_info(), so keep it out of active decode
        // ticks once the enforcer is running" (cache-once).
        KernelRule {
            rule_id: "gpu-api-thread-affinity-snapshot-metrics".to_string(),
            gpu_concept: "A background monitor or enforcer thread must never call GPU runtime APIs while the GPU engine is executing requests — an API call off the execution thread corrupts command-buffer internal state, and a pressure-triggered buffer-cache clear issued from the wrong thread races the runtime's async completion callbacks (the SIGABRT / prepare-count-underflow class; field evidence on M3/M4 Metal). Three instantiations of the one discipline. (1) Snapshot: the GPU execution thread publishes the metrics the background thread needs — the last get_active_memory sample is recorded on the executor thread, and the enforcer combines that cached value with non-GPU kernel ledgers (phys_footprint), making zero runtime API calls while requests are active; the direct-API path is reserved for the idle regime, where precision matters and no command buffers are in flight. (2) Flag-and-defer: reclamation is triggered by setting an atomic per-owner flag; the actual clear runs on the inference thread at the next step boundary through the already lock-protected, engine-stream-synchronized path — which also fixes the busy-server gap of idle-only reclaim paths, which never fire while requests run and so cannot recover a loaded server from hard pressure. (3) Cache-once: immutable device caps (the effective Metal working-set cap, whose read may fall back to a device_info call or even a subprocess) are resolved once outside the poll hot path and cached in a field; the steady-state poll reads the field. Distinct from concurrent-context-init-needs-process-wide-lock (init-time construction race — this is steady-state API thread affinity), from no-blocking-sync-in-async-pipeline (bans blocking synchronization — this bans the API call itself from the wrong thread even when it would not block), and from the readback-timing family (WHEN device work completes vs WHICH THREAD may touch the runtime at all).".to_string(),
            ref_shape: "// naive: the background enforcer polls GPU state and clears the buffer\n// pool directly from its own thread while requests are executing\nstruct Gpu;\nimpl Gpu {\n    fn get_active_memory(&self) -> usize { 0 }\n    fn get_cache_memory(&self) -> usize { 0 }\n    fn clear_cache(&self) {}\n}\nstruct Sched; // owns the GPU execution thread\nconst HARD_LIMIT: usize = 64 * 1024 * 1024 * 1024;\nconst POLL: std::time::Duration = std::time::Duration::from_secs(1);\nfn spawn_enforcer_naive(gpu: Gpu, sched: Sched) {\n    std::thread::spawn(move || {\n        let _ = sched;\n        loop {\n            // GPU API OFF the execution thread while a request is in\n            // flight: corrupts command-buffer internal state\n            let active = gpu.get_active_memory();\n            let pool = gpu.get_cache_memory();\n            if active + pool > HARD_LIMIT {\n                gpu.clear_cache(); // races the async completion callbacks:\n            } // SIGABRT (M3) / prepare-count-underflow kernel panic (M4)\n            std::thread::sleep(POLL);\n        }\n    });\n}".to_string(),
            opt_pattern: "// optimized: the GPU thread PUBLISHES snapshots; the enforcer reads the\n// cache + kernel ledger (zero GPU API calls) and sets an ATOMIC FLAG; the\n// actual clear runs on the GPU thread at the next step boundary through\n// the already-synchronized path. Immutable device caps cached once.\nuse std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};\nuse std::sync::Arc;\nstruct ExecState {\n    last_active_bytes: AtomicUsize, // written ONLY on the GPU exec thread\n    reclaim_requested: AtomicBool,  // set by the enforcer (atomic flag)\n    metal_cap_bytes: usize,         // cache-once: immutable device cap\n}\nstruct Sched2 {\n    state: Arc<ExecState>,\n}\nimpl Sched2 {\n    fn step(&self, gpu_active: usize) {\n        // runs ON the GPU execution thread:\n        self.state.last_active_bytes.store(gpu_active, Ordering::Relaxed); // publish\n        if self.state.reclaim_requested.swap(false, Ordering::AcqRel) {\n            // the ACTUAL buffer-pool clear runs HERE (GPU thread, step\n            // boundary) through the lock-protected engine-stream-synced\n            // path — fires even while requests run, unlike idle-only\n            // reclaim, which never fires under load\n        }\n    }\n}\nconst POLL2: std::time::Duration = std::time::Duration::from_secs(1);\nfn spawn_enforcer_affine(state: Arc<ExecState>, phys_footprint: usize) {\n    std::thread::spawn(move || loop {\n        // snapshot read: NO GPU API call from this thread\n        let active = state.last_active_bytes.load(Ordering::Relaxed);\n        let current = active.max(phys_footprint); // + kernel ledger only\n        if current > state.metal_cap_bytes {\n            state.reclaim_requested.store(true, Ordering::Release); // flag\n        } // and defer: the clear belongs to the GPU thread's next step\n        std::thread::sleep(POLL2);\n    });\n}".to_string(),
        },
        // ── skip-unchanged-writes-via-dirty-encoding ── distilled from the
        // frguthmann compute-shader optimization writeup (Part 1, 2020;
        // GLSL/Vulkan Game-of-Life, Nsight-driven, honest failed-
        // experiments list): the pass's unconditional dst[i] = src[i] copy
        // for unchanged cells was 20% of all L2 traffic; the dirty-encoding
        // elision took the sparse-grid pass ~20% faster (11.5ms -> ~9.5ms,
        // 20k x 20k, RTX 2070) and measured WORSE on random/dense fill
        // (13.5ms) — the regime gate is load-bearing, encoded in-concept.
        // The encoding piggyback (dirty = plain + 2, no side buffer) plus
        // the lazy alternate-rotation cleanup is the decision content; the
        // source's own 'updated in the last rotation' comment is imprecise
        // (the bit may be older) but the write-back is idempotent, which is
        // exactly why the lazy schedule stays sound.
        KernelRule {
            rule_id: "skip-unchanged-writes-via-dirty-encoding".to_string(),
            gpu_concept: "Per-element write elision for ping-pong state buffers via a dirty bit piggybacked on the element's own encoding. A pass that unconditionally copies unchanged elements to the destination buffer (dst[i] = src[i], 'so the data is there next step') pays full write bandwidth for zero information — measured on a stencil pass, the unconditional copy alone put WRITES at 20% of all L2 traffic (9 reads : 1 write per element). Encode 'just updated' IN the value: states 0/1 = plain dead/alive, 2/3 = just-updated dead/alive — liveness stays readable through the offset because dirty = plain + 2 preserves state % 2; write back ONLY elements that transitioned this step (store the dirty value) or still carry the dirty bit from a prior step (store value - 2, the lazy cleanup). The cleanup is lazy, not immediate: after a change at step N the cell writes on ALTERNATE rotations until it changes again (each cleanup lands the correct plain value; the idempotent write-back is what makes the lazy schedule sound). Cost model per element class: never-changed -> ZERO writes (vs 1/step naive); changed-once-then-stable -> a write on alternate rotations; changed-every-step -> the SAME write count as naive PLUS encoding arithmetic and a branch — strictly worse per cell. REGIME-GATED both directions (Nsight, RTX 2070, 20k x 20k grid): sparse dynamics (single glider) ~20% faster, 11.5ms -> ~9.5ms, L2 write share collapses (99.7% of L2 traffic becomes L1TEX reads, SM becomes the 75% top-throughput unit); dense dynamics (random fill) measures WORSE than the naive unconditional copy, 13.5ms vs 11.5ms — apply only when the changed fraction is structurally small (event-driven sims, sparse updates, converge-and-idle iterations), never for dense churn. Distinct from predicate-gated-skip-empty-workset-step (whole-STEP elision on a host-side 0-count guard — this is per-ELEMENT store elision inside the kernel via data-encoded state), from skip-all-zero-packed-words-via-or-reduce (skips COMPUTE on all-zero input words — this skips WRITES of unchanged output elements), and from write-before-read-state-skips-checkpoint (elides speculative CHECKPOINTS on append-only caches repaired by re-execution — this elides output WRITES on ping-pong state, repaired by the lazy cleanup).".to_string(),
            ref_shape: "// naive: every element writes dst every step — unchanged cells pay full write\n// bandwidth for zero information (measured: the copy alone put WRITES at 20%\n// of all L2 traffic on a 9-read-1-write stencil)\nfn sim_step_naive(src: &[u32], dst: &mut [u32], grid: usize) {\n    for idx in 0..grid * grid {\n        let alive = count_neighbors(src, grid, idx);\n        let state = src[idx];\n        let is_alive = state == 1;\n        if !is_alive && alive == 3 {\n            dst[idx] = 1; // born\n        } else if is_alive && (alive < 2 || alive > 3) {\n            dst[idx] = 0; // died\n        } else {\n            dst[idx] = state; // the unconditional copy — paid by EVERY unchanged cell\n        }\n    }\n}\nfn count_neighbors(_src: &[u32], _grid: usize, _idx: usize) -> u32 {\n    0\n}".to_string(),
            opt_pattern: "// optimized: dirty bit piggybacked on the encoding — 0/1 plain, 2/3 =\n// just-updated; write back only transitioned or still-dirty elements\nfn sim_step_dirty(src: &[u32], dst: &mut [u32], grid: usize) {\n    for idx in 0..grid * grid {\n        let alive = count_neighbors(src, grid, idx);\n        let state = src[idx];\n        let is_alive = state % 2 == 1; // parity survives the +2 dirty offset\n        if !is_alive && alive == 3 {\n            dst[idx] = 3; // born + dirty\n        } else if is_alive && (alive < 2 || alive > 3) {\n            dst[idx] = 2; // died + dirty\n        } else if state > 1 {\n            dst[idx] = state - 2; // lazy cleanup: restore the plain encoding\n        }\n        // else: unchanged AND clean -> NO WRITE (the elision)\n    }\n}\n// cost model: never-changed cells -> ZERO writes; changed-once -> alternate\n// rotations; changed-every-step -> SAME count as naive + overhead. Sparse\n// dynamics ~20% faster (11.5ms -> ~9.5ms, 20k x 20k); dense dynamics WORSE\n// (13.5ms vs 11.5ms) — regime-gated, apply only on structurally small\n// changed fractions.\nfn count_neighbors(_src: &[u32], _grid: usize, _idx: usize) -> u32 {\n    0\n}".to_string(),
        },
    ]
}
